    unsigned char* ciphertext = (unsigned char*)malloc(data_len + AES_BLOCK_SIZE);
    if (!ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        result.key = NULL;
        result.iv = NULL;
        return result; // Memory allocation failed
