        EVP_CIPHER_CTX_free(ctx);
        free(actual_key);
        free(iv);
        free(ciphertext);
        result.key = NULL;
        result.iv = NULL;
        return result; // EVP_EncryptUpdate failed
    }
    ciphertext_len = len;

